#include "tigersheets/session.hpp"
#include "tigersheets/financial_models.hpp"
#include <iostream>
#include <stdexcept>
using namespace tigersheets;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{
 WorkbookSession session({{"revision",0},{"sheets",Json::array({{{"id","s"},{"name","Model"},{"cells",Json::array({{{"row",1},{"col",1},{"input","10"},{"style",{{"numberFormat","0.00"}}}},{{"row",2},{"col",1},{"input","=A1*2"}}})}}})}});
 const Json definition={{"version",1},{"id","upside"},{"name","Upside"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",1},{"col",1},{"type","number"},{"value",12}}})}};std::string error;
 const bool saved=session.apply(0,Json::array({{{"type","save_financial_definition"},{"definition",definition}}}),&error);require(saved,error.c_str());require(session.snapshotView().at("financialModels")[0]==definition&&session.cellAt("s",1,1)->at("input")=="10","saving a scenario records its definition without applying assumptions");
 const bool applied=session.apply(1,Json::array({{{"type","apply_financial_scenario"},{"id","upside"}}}),&error);require(applied,error.c_str());require(session.cellAt("s",1,1)->at("input")=="12"&&session.cellAt("s",2,1)->at("input")=="=A1*2","applying a saved scenario changes only its input constants");require(session.cellAt("s",1,1)->at("style").at("numberFormat")=="0.00","scenario application retains input formats");
 require(session.undo()&&session.cellAt("s",1,1)->at("input")=="10"&&session.snapshotView().contains("financialModels"),"one Undo reverses the applied assumptions");require(session.undo()&&!session.snapshotView().contains("financialModels"),"the previous Undo removes the saved scenario");require(session.redo()&&session.redo()&&session.cellAt("s",1,1)->at("input")=="12","Redo restores saved setup and applied values separately");
 const auto before=session.snapshot();require(!session.apply(before.at("revision"),Json::array({{{"type","set_metadata"},{"key","financialModels"},{"value",Json::array()}}}),&error)&&session.snapshotView()==before,"generic metadata cannot bypass typed financial model ownership");
 const Json forecast={{"version",1},{"id","forecast"},{"name","Forecast"},{"kind","forecast"},{"periods",2},{"drivers",Json::array({{{"name","Revenue"},{"base",{{"sheet","s"},{"row",1},{"col",1}}},{"growth",0.1}}})},{"output",{{"sheet","s"},{"row1",5},{"col1",1}}}};CalculationContext context;context.snapshot=session.snapshot();context.generation=3;const auto generation=generateFinancialModel(context.snapshot,forecast,context);const bool reported=session.apply(before.at("revision"),financialModelOperations(before,generation),&error);require(reported,error.c_str());const auto reportIndex=session.snapshotView().at("financialModels").size()-1;const bool edited=session.apply(session.snapshotView().at("revision"),Json::array({{{"type","set_cell"},{"sheet","s"},{"row",1},{"col",1},{"input","15"}}}),&error);require(edited,error.c_str());require(session.snapshotView().at("financialModels")[reportIndex].at("stale")==true,"source changes mark committed financial output stale");require(session.undo()&&session.snapshotView().at("financialModels")[reportIndex].at("stale")==false,"undo of a source edit restores the previous financial report freshness");require(session.redo()&&session.snapshotView().at("financialModels")[reportIndex].at("stale")==true,"redo restores source edits and report freshness together");std::cout<<"financial model session tests passed\n";
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
